using System;using System.IO;using System.Drawing;using System.Linq;using System.Windows.Forms;using System.Threading.Tasks;using System.Collections.Generic;
sealed partial class WorkspaceWindow {
 async Task<Dictionary<string,object>> CompanionUiState(WorkTab tab,string action){string path=Path.Combine(tab.folder,"test-result.json");File.Delete(path);Command(tab,"test-ui",new Dictionary<string,object>{{"action",action}});for(int i=0;i<100&&!File.Exists(path);i++)await Task.Delay(50);if(!File.Exists(path))throw new Exception("Companion control timed out: "+action);return json.Deserialize<Dictionary<string,object>>(ReadShared(path));}
 async Task CompanionLayoutRegression(){var checks=new List<string>();try{int expected=Int32.Parse(File.ReadAllText(Path.Combine(root,"expected-companion-pid.txt")));var tab=await OpenCompanion(true);if(tab==null||!tab.attached||tab.process.Id!=expected)throw new Exception("Did not reuse the existing Companion");if(companionSideTab!=tab||tabs.SelectedTab!=home)throw new Exception("Home did not keep a true notes sidebar");checks.Add("Existing Companion from another suite scope is reused beside Home");await CaptureTab(tab);if(!ReadShared(Path.Combine(tab.folder,"snapshot.json")).Contains("Workscape retained note"))throw new Exception("Existing note was replaced");Command(tab,"test-status");await Task.Delay(900);var attachedStatus=json.Deserialize<Dictionary<string,object>>(ReadShared(Path.Combine(tab.folder,"test-result.json")));if(GetParent(new IntPtr(Convert.ToInt64(attachedStatus["handle"])))!=tab.panel.Handle)throw new Exception("Companion lost its native parent after docking");if(!Convert.ToBoolean(attachedStatus["visible"]))throw new Exception("Companion is hidden after docking");checks.Add("The current note stays intact and its live native window is visible in the dock");var controls=await CompanionUiState(tab,"memo-on");if(!Convert.ToBoolean(controls["topVisible"])||!Convert.ToBoolean(controls["quickVisible"]))throw new Exception("Saved memo preference hid embedded navigation");controls=await CompanionUiState(tab,"all-notes");if(!Convert.ToBoolean(controls["listVisible"])||Convert.ToBoolean(controls["pageVisible"]))throw new Exception("All notes failed in the narrow sidebar");if(Convert.ToBoolean(controls["standaloneCompact"]))throw new Exception("Docking changed standalone compact preference");controls=await CompanionUiState(tab,"current-note");if(Convert.ToBoolean(controls["listVisible"])||!Convert.ToBoolean(controls["pageVisible"]))throw new Exception("Current note failed in narrow sidebar");controls=await CompanionUiState(tab,"task-view");if(Convert.ToString(controls["view"])!="Tasks")throw new Exception("Embedded task view failed");await CompanionUiState(tab,"note-view");controls=await CompanionUiState(tab,"new-note");await Task.Delay(1000);await Tick();if(companionSideTab!=tab||tabs.SelectedTab!=home||!Convert.ToBoolean(controls["pageVisible"]))throw new Exception("New note unexpectedly replaced the sidebar with a full tab");checks.Add("All notes, Current note, task switching and New note work inside the dock without inherited memo/compact modes hiding controls");foreach(var size in new[]{new Size(1040,760),new Size(1480,980)}){ClientSize=size;Application.DoEvents();await Task.Delay(150);if(companionSide.Panel2.Width<300||companionSide.Panel2.Width>430)throw new Exception("Sidebar width is wrong");using(var shot=new Bitmap(Width,Height)){DrawToBitmap(shot,new Rectangle(0,0,Width,Height));shot.Save(Path.Combine(root,"side-"+size.Width+".png"));}}checks.Add("Narrow sidebar keeps its width at both window sizes");var primary=new WorkTab{id=Guid.NewGuid().ToString(),studio="wobble",folder=Path.Combine(root,"FakeStudio"),title="Test artwork",page=new TabPage("Test artwork"),panel=new Panel{Dock=DockStyle.Fill},process=System.Diagnostics.Process.GetCurrentProcess(),attached=true};Directory.CreateDirectory(primary.folder);primary.page.Controls.Add(primary.panel);primary.panel.Controls.Add(new Label{Text="Your studio stays visible",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter});items.Add(primary);tabs.TabPages.Add(primary.page);tabs.SelectedTab=primary.page;await SelectTab();if(!IsVisibleTab(tab)||!IsVisibleTab(primary))throw new Exception("Sidebar is not active beside the studio");await OpenCompanion(false);if(companionSide!=null||tabs.SelectedTab!=tab.page||tab.process.Id!=expected)throw new Exception("Full tab failed");await OpenCompanion(true);if(companionSideTab!=tab||tabs.SelectedTab!=primary.page)throw new Exception("Narrow mode failed when Companion was selected");await OpenCompanion(false);controls=await CompanionUiState(tab,"all-notes");if(!Convert.ToBoolean(controls["listVisible"])||!Convert.ToBoolean(controls["pageVisible"]))throw new Exception("Wide All notes should show list beside note");controls=await CompanionUiState(tab,"current-note");if(Convert.ToBoolean(controls["listVisible"]))throw new Exception("Wide Current note did not hide list");controls=await CompanionUiState(tab,"menu-open");if(!Convert.ToBoolean(controls["menuVisible"]))throw new Exception("Embedded Pages menu failed");await CompanionUiState(tab,"menu-close");await OpenCompanion(true);checks.Add("Full tab and narrow panel switch without replacing the live process");await FloatCompanion();if(!tab.detached||tab.process.HasExited)throw new Exception("Floating lost the live process");var floating=json.Deserialize<Dictionary<string,object>>(ReadShared(Path.Combine(tab.folder,"floating.json")));if(!Convert.ToBoolean(floating["topmost"])||GetParent(new IntPtr(Convert.ToInt64(floating["handle"])))!=IntPtr.Zero)throw new Exception("Floating is not independent and on top");Activate();await Task.Delay(300);Command(tab,"test-status");await Task.Delay(1000);var state=json.Deserialize<Dictionary<string,object>>(ReadShared(Path.Combine(tab.folder,"test-result.json")));if(!Convert.ToBoolean(state["topmost"]))throw new Exception("Floating lost Always on top");checks.Add("Float detaches the same Companion and retains Always on top after Workscape activates");await OpenCompanion(true);if(companionSideTab!=tab||tab.process.Id!=expected)throw new Exception("Floating could not return to the side panel");checks.Add("Floating returns to the side panel with the same note");foreach(string old in Directory.GetFiles(primary.folder,"command-*.json"))File.Delete(old);var refusal=Task.Run(async()=>{for(int i=0;i<100;i++){if(Directory.GetFiles(primary.folder,"command-*.json").Any(f=>ReadShared(f).Contains("capture"))){Atomic(Path.Combine(primary.folder,"snapshot.json"),json.Serialize(new{error="test capture refusal"}));return;}await Task.Delay(40);}});await CloseAllTabs(false);await refusal;if(items.Count!=2||tab.process.HasExited)throw new Exception("Close all did not stop at a failed capture");checks.Add("Close all stops if a studio cannot capture its work");primary.process=null;await CloseAllTabs(false);if(items.Count!=0||tabs.SelectedTab!=home||tab.process.HasExited)throw new Exception("Close all did not release Companion safely");checks.Add("Close all removes tabs and returns Companion to its tray process");Atomic(Path.Combine(root,"result.json"),json.Serialize(new{ok=true,checks}));}catch(Exception e){Atomic(Path.Combine(root,"result.json"),json.Serialize(new{ok=false,error=e.ToString(),checks}));}allowClose=true;Close();}
}
